(()=>{
const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog=[],current=null,exampleFiles=[],timer=null,runs=[],scheduleId=null;
async function api(path,body,method=body?'POST':'GET'){const response=await fetch('/api/runtime/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let value;try{value=await response.json();}catch{throw Error('Open the private runtime preview to execute capabilities. The static library does not run the local engine.');}if(!response.ok)throw Error(value.error||'Request failed.');return value;}
const showError=message=>{$('#form-error').hidden=false;$('#form-error').textContent=message;};
function selected(){return catalog.find(c=>c.id===$('#capability-select').value);}
function choices(){const query=$('#capability-search').value.toLowerCase();const previous=$('#capability-select').value;$('#capability-select').innerHTML=catalog.filter(c=>(c.name+' '+c.family).toLowerCase().includes(query)).map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');if([...$('#capability-select').options].some(o=>o.value===previous))$('#capability-select').value=previous;describe();}
function describe(){const c=selected();if(!c)return;$('#capability-description').textContent=c.family;$('#required-inputs').textContent='Bring: '+c.inputs.join(' · ');$('#task').placeholder=c.example;if(c.missing_tools?.length){$('#required-inputs').textContent+=' · Local setup needed: '+c.missing_tools.join(', ');}if(!current||!['queued','running'].includes(current.status))$('#run-button').disabled=!c.available;}
function markdown(text){const lines=text.split('\n'),out=[];let code=false,buffer=[];for(const line of lines){if(line.startsWith('```')){if(code){out.push('<pre>'+escape(buffer.join('\n'))+'</pre>');buffer=[];}code=!code;continue;}if(code){buffer.push(line);continue;}if(line.startsWith('### '))out.push('<h4>'+escape(line.slice(4))+'</h4>');else if(line.startsWith('## '))out.push('<h3>'+escape(line.slice(3))+'</h3>');else if(line.startsWith('# '))out.push('<h3>'+escape(line.slice(2))+'</h3>');else if(line.trim().startsWith('{')&&line.trim().endsWith('}')){try{out.push('<pre>'+escape(JSON.stringify(JSON.parse(line),null,2))+'</pre>');}catch{out.push('<p>'+escape(line)+'</p>');}}else if(line)out.push('<p>'+escape(line).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')+'</p>');}if(buffer.length)out.push('<pre>'+escape(buffer.join('\n'))+'</pre>');return out.join('');}
function renderHistory(){ $('#history-list').innerHTML=runs.filter(run=>(run.name+' '+run.status).toLowerCase().includes($('#history-search').value.toLowerCase())).slice(0,$('#history-search').value?100:12).map(r=>`<button type="button" data-run="${r.id}">${escape(r.name)} · ${escape(r.status)}</button>`).join('')||'Completed work will appear here.';}
function artifactPreview(job){const preview=$('#artifact-preview');preview.replaceChildren();const files=job.files||[];const html=files.find(f=>f.mime==='text/html'),video=files.find(f=>f.mime==='video/mp4'),image=files.find(f=>f.mime==='image/svg+xml'),audio=files.find(f=>f.mime==='audio/wav');const file=html||video||image||audio;if(!file)return;const label=document.createElement('p');label.className='preview-label';label.textContent='Actual generated artifact · '+file.name;preview.append(label);let view;if(html){view=document.createElement('iframe');view.sandbox='allow-scripts';view.title='Generated '+job.name+' preview';view.src=file.url;}else if(video){view=document.createElement('video');view.controls=true;view.preload='metadata';view.src=file.url;}else if(image){view=document.createElement('img');view.alt='Generated '+job.name+' diagram or map';view.src=file.url;}else{view=document.createElement('audio');view.controls=true;view.src=file.url;}preview.append(view);}
function render(job){const changed=current?.id!==job.id||current?.status!==job.status;current=job;$('#run-status').textContent=job.status.replaceAll('_',' ');$('#run-status').dataset.status=job.status;$('#results-heading').textContent=job.title||job.name;$('#run-progress').textContent=job.error||job.activity?.at(-1)?.message||'Queued';$('#result-content').innerHTML=job.content?markdown(job.content):'';$('#activity-list').innerHTML=(job.activity||[]).map(a=>'<li>'+escape(a.message)+'</li>').join('');$('#receipt-summary').textContent=JSON.stringify({tool_steps:job.receipts||[],external_writes:job.external_writes,computed:job.computed||{}},null,2);$('#files-section').hidden=!job.files?.length;$('#file-list').innerHTML=(job.files||[]).map(f=>`<div class="file-card"><a href="${f.url}?download=1" download="${escape(f.name)}">${escape(f.name)} ↓</a><small>${Math.ceil(f.size/1024)} KB · ${escape(f.mime)}</small></div>`).join('');$('#pending-action').hidden=!job.pending_action;if(job.pending_action)$('#action-preview').textContent=JSON.stringify(job.pending_action,null,2);$('#routine-action').hidden=!job.proposed_routine;if(job.proposed_routine)$('#routine-preview').textContent=JSON.stringify(job.proposed_routine,null,2);const active=['queued','running'].includes(job.status);$('#run-button').disabled=active||!selected()?.available;$('#cancel-button').hidden=!active;if(changed){if(job.files?.length)artifactPreview(job);else $('#artifact-preview').replaceChildren();}const index=runs.findIndex(r=>r.id===job.id);if(index>=0)runs[index]=job;else runs.unshift(job);renderHistory();}
async function poll(id){clearTimeout(timer);try{const job=await api('jobs/'+id);render(job);if(['queued','running'].includes(job.status))timer=setTimeout(()=>poll(id),1200);}catch(error){showError(error.message);$('#run-button').disabled=false;}}
$('#capability-search').addEventListener('input',choices);$('#capability-select').addEventListener('change',()=>{describe();exampleFiles=[];$('#uploads').value='';$('#upload-list').textContent='No files selected.';$('#example-note').hidden=true;});
$('#load-example').addEventListener('click',async()=>{try{const sample=await api('examples/'+selected().id);$('#task').value=sample.task;$('#context').value=sample.context;$('#structured-inputs').value=JSON.stringify(sample.inputs,null,2);$('#research').checked=sample.research;exampleFiles=sample.files;$('#uploads').value='';$('#upload-list').textContent=sample.files.length?sample.files.map(f=>f.name).join(' · '):'This example uses the supplied text and structured data.';$('#example-note').hidden=false;$('#form-error').hidden=true;}catch(error){showError(error.message);}});
$('#uploads').addEventListener('change',()=>{exampleFiles=[];$('#upload-list').textContent=[...$('#uploads').files].map(f=>f.name).join(' · ')||'No files selected.';});
async function upload(file){if(file.size>10_000_000)throw Error('Each uploaded file must be smaller than 10 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name.replace(/[^a-zA-Z0-9_.-]/g,'-'),base64:reader.result.split(',')[1]});reader.onerror=()=>reject(Error('Could not read '+file.name));reader.readAsDataURL(file);});}
$('#run-form').addEventListener('submit',async event=>{event.preventDefault();$('#form-error').hidden=true;try{const c=selected();if(!c)throw Error('Choose a capability.');$('#run-button').disabled=true;const files=exampleFiles.length?exampleFiles:await Promise.all([...$('#uploads').files].map(upload));const job=await api('jobs',{capabilityId:c.id,task:$('#task').value,context:$('#context').value,inputs:JSON.parse($('#structured-inputs').value||'{}'),files,research:$('#research').checked});render(job);$('#results-heading').scrollIntoView({behavior:'smooth',block:'start'});poll(job.id);}catch(error){showError(error.message);$('#run-button').disabled=false;}});
$('#cancel-button').addEventListener('click',async()=>{if(current)render(await api('jobs/'+current.id+'/cancel',{}));});
$('#approve-action').addEventListener('click',async()=>{try{const action=current.pending_action;render(await api('actions/approve',{nonce:action.nonce,sha256:action.sha256}));}catch(error){showError(error.message);}});
$('#activate-routine').addEventListener('click',async()=>{try{const result=await api('routines',{sourceJobId:current.id,approved:true});scheduleId=result.id;$('#stop-routine').hidden=false;$('#activate-routine').disabled=true;$('#routine-preview').textContent=JSON.stringify(result,null,2);}catch(error){showError(error.message);}});
$('#stop-routine').addEventListener('click',async()=>{try{await api('routines/'+scheduleId,null,'DELETE');$('#stop-routine').hidden=true;$('#activate-routine').disabled=false;$('#routine-preview').textContent='Routine stopped.';}catch(error){showError(error.message);}});
$('#history-list').addEventListener('click',event=>{const button=event.target.closest('[data-run]');if(button)poll(button.dataset.run);});
$('#history-search').addEventListener('input',renderHistory);
(async()=>{try{const state=await api('catalog');catalog=state.capabilities;runs=state.runs;choices();const requested=new URLSearchParams(location.search).get('capability');const c=catalog.find(c=>c.slug===requested||c.id===requested);if(c){$('#capability-select').value=c.id;describe();}$('#connection-state').textContent=state.connection.connected?'● Connected to your Codex account':'Codex sign-in required';$('#run-button').disabled=!selected()?.available;api('verification').then(()=>$('#checks-link').hidden=false).catch(()=>{});renderHistory();const id=new URLSearchParams(location.search).get('run');if(id)poll(id);}catch(error){$('#connection-state').textContent='Local runtime connection required';$('#run-button').disabled=true;showError(error.message);}})();
})();
